import _g from "./globals.js";

export function getRowData(top = 0) {
  return scenes[_g.scene].split("\n")[top].split("|");
}

/** returns the name of the icon image */
export function getCellImage(top = 0, left = 0) {
  return getRowData(top)[2 * left];
}

/** returns the icon type of the cell */
export function getCellType(top = 0, left = 0) {
  return getRowData(top)[2 * left + 1];
}

/** returns the cell icon and data */
export function getCellData(top = 0, left = 0) {
  const row = getRowData(top);
  return {
    imgType: row[2 * left],
    cellType: row[2 * left + 1],
  };
}

/** update the cell data within the active scene */
export function updateScene(top = 0, left = 0, icon = "", data = "") {
  const row = getRowData(top);
  row[2 * left] = icon;
  row[2 * left + 1] = data;

  // update scene with new row
  const rows = scenes[_g.scene].split("\n");
  rows[top] = row.join("|");
  scenes[_g.scene] = rows.join("\n");
  //console.log(scenes[_g.scene]);
}

